import{_ as s,o as i,c as a,a3 as t}from"./chunks/framework.BZCmpA0A.js";const u=JSON.parse('{"title":"12 · 維護文件網站","description":"","frontmatter":{},"headers":[],"relativePath":"topics/writing.md","filePath":"topics/writing.md","lastUpdated":1793159406000}'),o={name:"topics/writing.md"};function n(r,e,p,l,d,c){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="_12-·-維護文件網站" tabindex="-1">12 · 維護文件網站 <a class="header-anchor" href="#_12-·-維護文件網站" aria-label="Permalink to &quot;12 · 維護文件網站&quot;">​</a></h1><p>你平常只要修改 Markdown（<code>.md</code>）文章。VitePress 負責把標題、表格與程式碼轉成可閱讀的網頁，不需要先寫 HTML 或 CSS。</p><h2 id="安裝與預覽" tabindex="-1">安裝與預覽 <a class="header-anchor" href="#安裝與預覽" aria-label="Permalink to &quot;安裝與預覽&quot;">​</a></h2><p>主機需要 Node.js 與 npm。本次文件工具為 VitePress 1.6.4；請以 repository 的 lockfile 安裝相同依賴。</p><p>網站來源在 repository 的 <code>codex/documentation</code> 分支。若要另外建立文件專用工作目錄，可使用 <code>git clone --branch codex/documentation --single-branch git@github.com:johnson931128/WUWAOS.git WUWAOS-docs</code>，之後進入該目錄再執行本章命令；main 的 OS 工作目錄不必為此切換分支。</p><p><code>package.json</code> 另固定 Vite 為 6.4.5，避開 VitePress 預設 Vite 5 依賴的已知開發伺服器問題；升級時也要重新確認建置、預覽與依賴檢查。</p><p>在專案根目錄 PowerShell 執行：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">npm.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ci</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">npm.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run docs:dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>打開終端印出的 Local 網址，預設為 <code>http://127.0.0.1:5173/</code>。如果連接埠已占用，以實際印出的網址為準。修改文章並儲存後，瀏覽器會更新。</p><p><code>npm.cmd ci</code> 用於首次安裝或同步 lockfile；平常直接執行 docs:dev 即可。重新安裝前先停止預覽，避免 Windows 因使用中的 esbuild.exe 無法替換而回報 EPERM。</p><p>這些指令在 Windows 主機執行，不是在 WUWAOS 的 <code>wuwaos&gt;</code> 輸入。按 Ctrl+C 停止預覽。</p><h2 id="新增一個主題" tabindex="-1">新增一個主題 <a class="header-anchor" href="#新增一個主題" aria-label="Permalink to &quot;新增一個主題&quot;">​</a></h2><ol><li>在 <code>docs/topics/</code> 新增 <code>.md</code> 檔，以既有章節為範本。</li><li>在 <code>docs/.vitepress/config.mts</code> 的 chapters 加入標題與檔名。</li><li>寫清楚問題、目前設計、來源檔、QEMU 操作與限制。</li><li>執行建置，並在瀏覽器確認導覽與文章顯示。</li></ol><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">npm.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run docs:build</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">npm.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run docs:preview</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>preview 預設為 <code>http://127.0.0.1:4173/</code>，顯示建置後的靜態網站。產物位於 <code>docs/.vitepress/dist/</code>，不納入 Git。</p><h2 id="原始碼只連到-github" tabindex="-1">原始碼只連到 GitHub <a class="header-anchor" href="#原始碼只連到-github" aria-label="Permalink to &quot;原始碼只連到 GitHub&quot;">​</a></h2><p>文章不內嵌 OS 程式碼，不匯入 C／組合語言來源檔。需要閱讀原始碼時，使用指向 GitHub 已提交版本的連結；尚未提交的實作要明確標示，不能建立不存在的檔案連結。架構文字、函式名稱、流程圖與操作指令仍保留在網站。</p><p>一般內部連結使用相對 Markdown 路徑，例如 <code>[記憶體](./memory.md)</code>；VitePress 會轉成網站連結並檢查不存在的頁面。</p><h2 id="現行文件與歷史規格" tabindex="-1">現行文件與歷史規格 <a class="header-anchor" href="#現行文件與歷史規格" aria-label="Permalink to &quot;現行文件與歷史規格&quot;">​</a></h2><p>網站現在支援 Mermaid：Markdown 的 mermaid 圍欄會在瀏覽器轉成流程圖。圖表語法仍由 GitHub 文件來源管理，套件隨網站建置並由 GitHub Pages 提供，不呼叫外部圖表服務；深淺色切換會重畫。一般 C／組合語言原始碼仍只提供 GitHub 連結。</p><p><code>docs/topics/</code> 解釋目前實作；<code>docs/SPEC-*.md</code> 保存各階段原始規格與驗收紀錄。新功能完成後要更新主題章節，再於<a href="./../history.html">歷史索引</a> 加入新規格，不要把舊驗收數字改成新版本結果。</p><p>課程筆記的檔案名稱以文字標示。本站沒有直接發布 <code>notes/</code> 全文；若未來要加入下載，應先確認內容與發布範圍。</p><h2 id="公開網站與發布權限" tabindex="-1">公開網站與發布權限 <a class="header-anchor" href="#公開網站與發布權限" aria-label="Permalink to &quot;公開網站與發布權限&quot;">​</a></h2><p>公開網址為 <a href="https://johnson931128.github.io/WUWAOS/" target="_blank" rel="noreferrer">WUWAOS 實作紀錄</a>。GitHub repository 是唯一的文章與網站程式碼來源，GitHub Pages 只提供靜態內容。公開網站沒有編輯、上傳、登入後台、來源切換或接收內容寫入的 API，也沒有部署憑證。</p><p>修改與發布必須具備 GitHub repository 寫入權限；單純知道網址、下載網頁或 fork repository，不會取得修改本站的權限。瀏覽器仍必須下載生成後的 HTML／CSS／JavaScript，不能把這些前端產物隱藏。</p><p>維護者確認文件後，在本機 PowerShell 執行發布工具：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">powershell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">File tools</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">publish-docs.ps1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>工具先把文件、網站設定與發布腳本保存到 johnson931128/WUWAOS 的 codex/documentation 分支，再把靜態產物發布到 gh-pages，不接受網頁訪客傳入來源或目的地。使用獨立 Git index（暫存索引）與明確的文件路徑清單，不切換 main、不提交 OS 原始碼、不更動既有暫存內容，也不 force push。</p><h2 id="google-搜尋" tabindex="-1">Google 搜尋 <a class="header-anchor" href="#google-搜尋" aria-label="Permalink to &quot;Google 搜尋&quot;">​</a></h2><p>網站提供靜態 HTML、canonical（正式網址標記）及 sitemap.xml（網站地圖），沒有要求登入或禁止索引。這些讓搜尋引擎有機會抓取，不代表 Google 已收錄或保證排名。</p><p>專案子路徑下的 robots.txt 不是網域根目錄的爬蟲規則；根目錄 robots.txt 不存在時，Google 仍可抓取。若要主動提交網站地圖，可在 Google Search Console 驗證網站後提交 <code>https://johnson931128.github.io/WUWAOS/sitemap.xml</code>。本次不代替使用者登入 Google 或宣稱已提交。</p><p>官方參考：<a href="https://vitepress.dev/guide/what-is-vitepress" target="_blank" rel="noreferrer">VitePress 文件</a>、<a href="https://vitepress.dev/guide/deploy" target="_blank" rel="noreferrer">部署說明</a>。</p>`,32)])])}const b=s(o,[["render",n]]);export{u as __pageData,b as default};
